# From Re-ARC's dsl.py, Copyright (c) 2024 Michael Hodel, MIT License.
# types


from typing import (
    List,
    Union,
    Tuple,
    Any,
    Container,
    Callable,
    FrozenSet,
    Iterable
)

Boolean = bool
Integer = int
IntegerTuple = Tuple[Integer, Integer]
Numerical = Union[Integer, IntegerTuple]
IntegerSet = FrozenSet[Integer]
Grid = Tuple[Tuple[Integer]]
Cell = Tuple[Integer, IntegerTuple]
Object = FrozenSet[Cell]
Objects = FrozenSet[Object]
Indices = FrozenSet[IntegerTuple]
IndicesSet = FrozenSet[Indices]
Patch = Union[Object, Indices]
Element = Union[Object, Grid]
Piece = Union[Grid, Patch]
TupleTuple = Tuple[Tuple]
ContainerContainer = Container[Container]



# constants


ZERO = 0
ONE = 1
TWO = 2
THREE = 3
FOUR = 4
FIVE = 5
SIX = 6
SEVEN = 7
EIGHT = 8
NINE = 9
TEN = 10
F = False
T = True

NEG_ONE = -1

ORIGIN = (0, 0)
UNITY = (1, 1)
DOWN = (1, 0)
RIGHT = (0, 1)
UP = (-1, 0)
LEFT = (0, -1)

NEG_TWO = -2
NEG_UNITY = (-1, -1)
UP_RIGHT = (-1, 1)
DOWN_LEFT = (1, -1)

ZERO_BY_TWO = (0, 2)
TWO_BY_ZERO = (2, 0)
TWO_BY_TWO = (2, 2)
THREE_BY_THREE = (3, 3)



# primitives


def identity(
    x: Any
) -> Any:
    \"\"\" identity function \"\"\"
    return x

def add(
    a: Numerical,
    b: Numerical
) -> Numerical:
    \"\"\" addition \"\"\"
    if isinstance(a, int) and isinstance(b, int):
        return a + b
    elif isinstance(a, tuple) and isinstance(b, tuple):
        return (a[0] + b[0], a[1] + b[1])
    elif isinstance(a, int) and isinstance(b, tuple):
        return (a + b[0], a + b[1])
    return (a[0] + b, a[1] + b)

def subtract(
    a: Numerical,
    b: Numerical
) -> Numerical:
    \"\"\" subtraction \"\"\"
    if isinstance(a, int) and isinstance(b, int):
        return a - b
    elif isinstance(a, tuple) and isinstance(b, tuple):
        return (a[0] - b[0], a[1] - b[1])
    elif isinstance(a, int) and isinstance(b, tuple):
        return (a - b[0], a - b[1])
    return (a[0] - b, a[1] - b)

def multiply(
    a: Numerical,
    b: Numerical
) -> Numerical:
    \"\"\" multiplication \"\"\"
    if isinstance(a, int) and isinstance(b, int):
        return a * b
    elif isinstance(a, tuple) and isinstance(b, tuple):
        return (a[0] * b[0], a[1] * b[1])
    elif isinstance(a, int) and isinstance(b, tuple):
        return (a * b[0], a * b[1])
    return (a[0] * b, a[1] * b)

def divide(
    a: Numerical,
    b: Numerical
) -> Numerical:
    \"\"\" floor division \"\"\"
    if isinstance(a, int) and isinstance(b, int):
        return a // b
    elif isinstance(a, tuple) and isinstance(b, tuple):
        return (a[0] // b[0], a[1] // b[1])
    elif isinstance(a, int) and isinstance(b, tuple):
        return (a // b[0], a // b[1])
    return (a[0] // b, a[1] // b)

def invert(
    n: Numerical
) -> Numerical:
    \"\"\" inversion with respect to addition \"\"\"
    return -n if isinstance(n, int) else (-n[0], -n[1])

def even(
    n: Integer
) -> Boolean:
    \"\"\" evenness \"\"\"
    return n % 2 == 0

def double(
    n: Numerical
) -> Numerical:
    \"\"\" scaling by two \"\"\"
    return n * 2 if isinstance(n, int) else (n[0] * 2, n[1] * 2)

def halve(
    n: Numerical
) -> Numerical:
    \"\"\" scaling by one half \"\"\"
    return n // 2 if isinstance(n, int) else (n[0] // 2, n[1] // 2)

def flip(
    b: Boolean
) -> Boolean:
    \"\"\" logical not \"\"\"
    return not b

def equality(
    a: Any,
    b: Any
) -> Boolean:
    \"\"\" equality \"\"\"
    return a == b

def contained(
    value: Any,
    container: Container
) -> Boolean:
    \"\"\" element of \"\"\"
    return value in container

def combine(
    a: Container,
    b: Container
) -> Container:
    \"\"\" union \"\"\"
    return type(a)((*a, *b))

def intersection(
    a: FrozenSet,
    b: FrozenSet
) -> FrozenSet:
    \"\"\" returns the intersection of two containers \"\"\"
    return a & b

def difference(
    a: Container,
    b: Container
) -> Container:
    \"\"\" difference \"\"\"
    return type(a)(e for e in a if e not in b)

def dedupe(
    iterable: Tuple
) -> Tuple:
    \"\"\" remove duplicates \"\"\"
    return tuple(e for i, e in enumerate(iterable) if iterable.index(e) == i)

def order(
    container: Container,
    compfunc: Callable
) -> Tuple:
    \"\"\" order container by custom key \"\"\"
    return tuple(sorted(container, key=compfunc))

def repeat(
    item: Any,
    num: Integer
) -> Tuple:
    \"\"\" repetition of item within vector \"\"\"
    return tuple(item for i in range(num))

def greater(
    a: Integer,
    b: Integer
) -> Boolean:
    \"\"\" greater \"\"\"
    return a > b

def size(
    container: Container
) -> Integer:
    \"\"\" cardinality \"\"\"
    return len(container)

def merge(
    containers: ContainerContainer
) -> Container:
    \"\"\" merging \"\"\"
    return type(containers)(e for c in containers for e in c)

def maximum(
    container: IntegerSet
) -> Integer:
    \"\"\" maximum \"\"\"
    return max(container, default=0)

def minimum(
    container: IntegerSet
) -> Integer:
    \"\"\" minimum \"\"\"
    return min(container, default=0)

def valmax(
    container: Container,
    compfunc: Callable
) -> Integer:
    \"\"\" maximum by custom function \"\"\"
    return compfunc(max(container, key=compfunc, default=0))

def valmin(
    container: Container,
    compfunc: Callable
) -> Integer:
    \"\"\" minimum by custom function \"\"\"
    return compfunc(min(container, key=compfunc, default=0))

def argmax(
    container: Container,
    compfunc: Callable
) -> Any:
    \"\"\" largest item by custom order \"\"\"
    return max(container, key=compfunc, default=None)

def argmin(
    container: Container,
    compfunc: Callable
) -> Any:
    \"\"\" smallest item by custom order \"\"\"
    return min(container, key=compfunc, default=None)

def mostcommon(
    container: Container
) -> Any:
    \"\"\" most common item \"\"\"
    return max(set(container), key=container.count)

def leastcommon(
    container: Container
) -> Any:
    \"\"\" least common item \"\"\"
    return min(set(container), key=container.count)

def initset(
    value: Any
) -> FrozenSet:
    \"\"\" initialize container \"\"\"
    return frozenset({value})

def both(
    a: Boolean,
    b: Boolean
) -> Boolean:
    \"\"\" logical and \"\"\"
    return a and b

def either(
    a: Boolean,
    b: Boolean
) -> Boolean:
    \"\"\" logical or \"\"\"
    return a or b

def increment(
    x: Numerical
) -> Numerical:
    \"\"\" incrementing \"\"\"
    return x + 1 if isinstance(x, int) else (x[0] + 1, x[1] + 1)

def decrement(
    x: Numerical
) -> Numerical:
    \"\"\" decrementing \"\"\"
    return x - 1 if isinstance(x, int) else (x[0] - 1, x[1] - 1)

def crement(
    x: Numerical
) -> Numerical:
    \"\"\" incrementing positive and decrementing negative \"\"\"
    if isinstance(x, int):
        return 0 if x == 0 else (x + 1 if x > 0 else x - 1)
    return (
        0 if x[0] == 0 else (x[0] + 1 if x[0] > 0 else x[0] - 1),
        0 if x[1] == 0 else (x[1] + 1 if x[1] > 0 else x[1] - 1)
    )

def positive(
    x: Integer
) -> Boolean:
    \"\"\" positive \"\"\"
    return x > 0

def toivec(
    i: Integer
) -> IntegerTuple:
    \"\"\" vector pointing vertically \"\"\"
    return (i, 0)

def tojvec(
    j: Integer
) -> IntegerTuple:
    \"\"\" vector pointing horizontally \"\"\"
    return (0, j)

def sfilter(
    container: Container,
    condition: Callable
) -> Container:
    \"\"\" keep elements in container that satisfy condition \"\"\"
    return type(container)(e for e in container if condition(e))

def mfilter(
    container: Container,
    function: Callable
) -> FrozenSet:
    \"\"\" filter and merge \"\"\"
    return merge(sfilter(container, function))

def extract(
    container: Container,
    condition: Callable
) -> Any:
    \"\"\" first element of container that satisfies condition \"\"\"
    return next(e for e in container if condition(e))

def totuple(
    container: FrozenSet
) -> Tuple:
    \"\"\" conversion to tuple \"\"\"
    return tuple(container)

def first(
    container: Container
) -> Any:
    \"\"\" first item of container \"\"\"
    return next(iter(container))

def last(
    container: Container
) -> Any:
    \"\"\" last item of container \"\"\"
    return max(enumerate(container))[1]

def insert(
    value: Any,
    container: FrozenSet
) -> FrozenSet:
    \"\"\" insert item into container \"\"\"
    return container.union(frozenset({value}))

def remove(
    value: Any,
    container: Container
) -> Container:
    \"\"\" remove item from container \"\"\"
    return type(container)(e for e in container if e != value)

def other(
    container: Container,
    value: Any
) -> Any:
    \"\"\" other value in the container \"\"\"
    return first(remove(value, container))

def interval(
    start: Integer,
    stop: Integer,
    step: Integer
) -> Tuple:
    \"\"\" range \"\"\"
    return tuple(range(start, stop, step))

def astuple(
    a: Integer,
    b: Integer
) -> IntegerTuple:
    \"\"\" constructs a tuple \"\"\"
    return (a, b)

def product(
    a: Container,
    b: Container
) -> FrozenSet:
    \"\"\" cartesian product \"\"\"
    return frozenset((i, j) for j in b for i in a)

def pair(
    a: Tuple,
    b: Tuple
) -> TupleTuple:
    \"\"\" zipping of two tuples \"\"\"
    return tuple(zip(a, b))

def branch(
    condition: Boolean,
    if_value: Any,
    else_value: Any
) -> Any:
    \"\"\" if else branching \"\"\"
    return if_value if condition else else_value

def compose(
    outer: Callable,
    inner: Callable
) -> Callable:
    \"\"\" function composition \"\"\"
    return lambda x: outer(inner(x))

def chain(
    h: Callable,
    g: Callable,
    f: Callable
) -> Callable:
    \"\"\" function composition with three functions \"\"\"
    return lambda x: h(g(f(x)))

def matcher(
    function: Callable,
    target: Any
) -> Callable:
    \"\"\" construction of equality function \"\"\"
    return lambda x: function(x) == target

def rbind(
    function: Callable,
    fixed: Any
) -> Callable:
    \"\"\" fix the rightmost argument \"\"\"
    n = function.__code__.co_argcount
    if n == 2:
        return lambda x: function(x, fixed)
    elif n == 3:
        return lambda x, y: function(x, y, fixed)
    else:
        return lambda x, y, z: function(x, y, z, fixed)

def lbind(
    function: Callable,
    fixed: Any
) -> Callable:
    \"\"\" fix the leftmost argument \"\"\"
    n = function.__code__.co_argcount
    if n == 2:
        return lambda y: function(fixed, y)
    elif n == 3:
        return lambda y, z: function(fixed, y, z)
    else:
        return lambda y, z, a: function(fixed, y, z, a)

def power(
    function: Callable,
    n: Integer
) -> Callable:
    \"\"\" power of function \"\"\"
    if n == 1:
        return function
    return compose(function, power(function, n - 1))

def fork(
    outer: Callable,
    a: Callable,
    b: Callable
) -> Callable:
    \"\"\" creates a wrapper function \"\"\"
    return lambda x: outer(a(x), b(x))

def apply(
    function: Callable,
    container: Container
) -> Container:
    \"\"\" apply function to each item in container \"\"\"
    return type(container)(function(e) for e in container)

def rapply(
    functions: Container,
    value: Any
) -> Container:
    \"\"\" apply each function in container to value \"\"\"
    return type(functions)(function(value) for function in functions)

def mapply(
    function: Callable,
    container: ContainerContainer
) -> FrozenSet:
    \"\"\" apply and merge \"\"\"
    return merge(apply(function, container))

def prapply(
    function: Callable,
    a: Container,
    b: Container
) -> FrozenSet:
    \"\"\" apply function on cartesian product \"\"\"
    return frozenset(function(i, j) for j in b for i in a)

def mostcolor(
    element: Element
) -> Integer:
    \"\"\" most common color \"\"\"
    values = [v for r in element for v in r] if isinstance(element, tuple) else [v for v, _ in element]
    return max(set(values), key=values.count)

def leastcolor(
    element: Element
) -> Integer:
    \"\"\" least common color \"\"\"
    values = [v for r in element for v in r] if isinstance(element, tuple) else [v for v, _ in element]
    return min(set(values), key=values.count)

def height(
    piece: Piece
