def joint_rule(d):
    # rows: even_rank by (barrow,barcol) among same color -> row 0 if even rank else 2
    # cols: XOR(more_same_above, rcol_lasthalf) -> '3': col2 if p else 0 ; '1': col5 if p else 3
    INFD=ALLINF[d]; CD=ALLCOL[d]
    bycolor={}
    for k in INFD: bycolor.setdefault(CD[k],[]).append(k)
    pred={}
    for col,ks in bycolor.items():
        sr=sorted(ks,key=lambda k:(INFD[k]['barrow'],INFD[k]['barcol']))
        sc=sorted(ks,key=lambda k:(INFD[k]['barcol'],INFD[k]['barrow']))
        for k in ks:
            rr=sr.index(k); n=len(sr); cr=sc.index(k)
            lasthalf = cr>=n/2
            above=sum(1 for q in ks if q!=k and INFD[q]['barrow']<INFD[k]['barrow'])
            below=sum(1 for q in ks if q!=k and INFD[q]['barrow']>INFD[k]['barrow'])
            ms=above>below
            p=(ms!=lasthalf)
            row = (0 if rr%2==0 else 2)
            c = (2 if p else 0) if col=='3' else (5 if p else 3)
            pred[k]=(row,c)
    return pred
